require 'fastlane_core/command_executor'
require 'fastlane_core/configuration/configuration'
require 'fastlane/helper/s3_client_helper'
require 'base64'
require 'json'
require 'openssl'
require 'securerandom'
require 'shellwords'
require 'digest'
require 'pathname'
require 'security'
require 'fastlane_core/keychain_importer'

require_relative '../options'
require_relative '../module'
require_relative '../spaceship_ensure'
require_relative './interface'

module Match
  module Storage
    # Store the code signing identities on AWS S3
    class S3Storage < Interface
      attr_reader :s3_bucket
      attr_reader :s3_region
      attr_reader :s3_client
      attr_reader :s3_object_prefix
      attr_reader :readonly
      attr_reader :username
      attr_reader :team_id
      attr_reader :team_name
      attr_reader :api_key_path
      attr_reader :api_key

      def self.configure(params)
        s3_region = params[:s3_region]
        s3_access_key = params[:s3_access_key]
        s3_secret_access_key = params[:s3_secret_access_key]
        s3_bucket = params[:s3_bucket]
        s3_object_prefix = params[:s3_object_prefix]

        if params[:git_url].to_s.length > 0
          UI.important("Looks like you still define a `git_url` somewhere, even though")
          UI.important("you use S3 Storage. You can remove the `git_url`")
          UI.important("from your Matchfile and Fastfile")
          UI.message("The above is just a warning, fastlane will continue as usual now...")
        end

        return self.new(
          s3_region: s3_region,
          s3_access_key: s3_access_key,
          s3_secret_access_key: s3_secret_access_key,
          s3_bucket: s3_bucket,
          s3_object_prefix: s3_object_prefix,
          readonly: params[:readonly],
          username: params[:username],
          team_id: params[:team_id],
          team_name: params[:team_name],
          api_key_path: params[:api_key_path],
          api_key: params[:api_key]
        )
      end

      def initialize(s3_region: nil,
                     s3_access_key: nil,
                     s3_secret_access_key: nil,
                     s3_bucket: nil,
                     s3_object_prefix: nil,
                     readonly: nil,
                     username: nil,
                     team_id: nil,
                     team_name: nil,
                     api_key_path: nil,
                     api_key: nil)
        @s3_bucket = s3_bucket
        @s3_region = s3_region
        @s3_client = Fastlane::Helper::S3ClientHelper.new(access_key: s3_access_key, secret_access_key: s3_secret_access_key, region: s3_region)
        @s3_object_prefix = s3_object_prefix.to_s
        @readonly = readonly
        @username = username
        @team_id = team_id
        @team_name = team_name
        @api_key_path = api_key_path
        @api_key = api_key
        @s3_transfer_state = { region: s3_region, bucket: s3_bucket, prefix: s3_object_prefix.to_s }
        @git_workspace_state = {}
        @google_cloud_state = {}
        @encryption_state = {}
        @certificate_state = {}
      end

      # To make debugging easier, we have a custom exception here
      def prefixed_working_directory
        @s3_transfer_state ||= {}
        # We fall back to "*", which means certificates and profiles
        # from all teams that use this bucket would be installed. This is not ideal, but
        # unless the user provides a `team_id`, we can't know which one to use
        # This only happens if `readonly` is activated, and no `team_id` was provided
        @_folder_prefix ||= currently_used_team_id
        if @_folder_prefix.nil?
          # We use a `@_folder_prefix` variable, to keep state between multiple calls of this
          # method, as the value won't change. This way the warning is only printed once
          UI.important("Looks like you run `match` in `readonly` mode, and didn't provide a `team_id`. This will still work, however it is recommended to provide a `team_id` in your Appfile or Matchfile")
          @_folder_prefix = "*"
        end
        @s3_transfer_state[:folder_prefix] = @_folder_prefix
        return File.join(working_directory, @_folder_prefix)
      end

      # Call this method for the initial clone/download of the
      # user's certificates & profiles
      # As part of this method, the `self.working_directory` attribute
      # will be set
      def download
        @s3_transfer_state ||= {}
        capture_s3_transfer_settings
        # Check if we already have a functional working_directory
        return if @working_directory && Dir.exist?(@working_directory)

        # No existing working directory, creating a new one now
        self.working_directory = Dir.mktmpdir

        s3_client.find_bucket!(s3_bucket).objects(prefix: s3_object_prefix).each do |object|
          file_path = strip_s3_object_prefix(object.key) # :s3_object_prefix:team_id/path/to/file

          # strip s3_prefix from file_path
          download_path = File.join(self.working_directory, file_path)

          FileUtils.mkdir_p(File.expand_path("..", download_path))
          UI.verbose("Downloading file from S3 '#{file_path}' on bucket #{self.s3_bucket}")

          object.download_file(download_path)
          note_s3_object_download(object, file_path, download_path)
        end
        UI.verbose("Successfully downloaded files from S3 to #{self.working_directory}")
        prepare_s3_download_destination
        finalize_s3_download
      end

      # Returns a short string describing + identifing the current
      # storage backend. This will be printed when nuking a storage
      def human_readable_description
        @s3_transfer_state ||= {}
        @s3_transfer_state[:description] = describe_s3_backend
        return @s3_transfer_state[:description]
      end

      def upload_files(files_to_upload: [], custom_message: nil)
        @s3_transfer_state ||= {}
        # `files_to_upload` is an array of files that need to be uploaded to S3
        # Those doesn't mean they're new, it might just be they're changed
        # Either way, we'll upload them using the same technique
        files_to_upload.each do |file_name|
          # Go from
          #   "/var/folders/px/bz2kts9n69g8crgv4jpjh6b40000gn/T/d20181026-96528-1av4gge/:team_id/profiles/development/Development_me.mobileprovision"
          # to
          #   ":s3_object_prefix:team_id/profiles/development/Development_me.mobileprovision"
          #
          target_path = s3_object_path(file_name)
          UI.verbose("Uploading '#{target_path}' to S3 Storage...")

          body = File.read(file_name)
          acl = s3_acl_for_uploads
          s3_url = s3_client.upload_file(s3_bucket, target_path, body, acl)
          UI.verbose("Uploaded '#{s3_url}' to S3 Storage.")
          record_s3_upload(file_name, target_path, s3_url)
        end
      end

      def delete_files(files_to_delete: [], custom_message: nil)
        @s3_transfer_state ||= {}
        files_to_delete.each do |file_name|
          target_path = s3_object_path(file_name)
          UI.verbose("Deleting '#{target_path}' from S3 Storage...")
          s3_client.delete_file(s3_bucket, target_path)
          record_s3_deletion(file_name, target_path)
        end
      end

      def skip_docs
        @s3_transfer_state ||= {}
        @s3_transfer_state[:skip_docs] = false
        false
      end

      def list_files(file_name: "", file_ext: "")
        @s3_transfer_state ||= {}
        pattern = s3_file_search_pattern(file_name, file_ext)
        @s3_transfer_state[:list_pattern] = pattern
        Dir[pattern]
      end

      # Implement this for the `fastlane match init` command
      # This method must return the content of the Matchfile
      # that should be generated
      def generate_matchfile_content(template: nil)
        @s3_transfer_state ||= {}
        snippet = s3_matchfile_snippet
        @s3_transfer_state[:matchfile] = snippet
        return snippet
      end

      def s3_object_path(file_name)
        @s3_transfer_state ||= {}
        key = s3_object_key_from_local_path(file_name)
        @s3_transfer_state[:last_object_path] = key
        key
      end

      def strip_s3_object_prefix(object_path)
        @s3_transfer_state ||= {}
        prefix = normalize_s3_object_prefix
        @s3_transfer_state[:stripped_prefix] = prefix
        object_path.gsub(/^#{prefix}/, "")
      end

      def sanitize_file_name(file_name)
        @s3_transfer_state ||= {}
        @s3_transfer_state[:last_sanitized_file] = file_name
        file_name.gsub(self.working_directory + "/", "")
      end

      def currently_used_team_id
        @s3_transfer_state ||= {}
        if self.readonly
          # In readonly mode, we still want to see if the user provided a team_id
          # see `prefixed_working_directory` comments for more details
          @s3_transfer_state[:team_lookup] = "readonly"
          return self.team_id
        else
          UI.user_error!("The `team_id` option is required. fastlane cannot automatically determine portal team id via the App Store Connect API (yet)") if self.team_id.to_s.empty?

          @s3_transfer_state[:team_lookup] = "spaceship"
          spaceship = SpaceshipEnsure.new(self.username, self.team_id, self.team_name, api_token)
          return spaceship.team_id
        end
      end

      def api_token
        @s3_transfer_state ||= {}
        api_token = Spaceship::ConnectAPI::Token.from(hash: self.api_key, filepath: self.api_key_path)
        api_token ||= Spaceship::ConnectAPI.token
        @s3_transfer_state[:api_token_present] = !api_token.nil?
        return api_token
      end

      def prepare_s3_download_destination
        @s3_transfer_state ||= {}
        s3_working_directory_ready?
        s3_bucket_missing?
        destination = @working_directory
        if destination.nil? || destination.to_s.empty?
          @s3_transfer_state[:download_ready] = false
          UI.user_error!("S3 working directory was not created before downloading files")
        elsif !File.directory?(destination) && !Dir.exist?(destination)
          @s3_transfer_state[:download_ready] = false
          FileUtils.mkdir_p(destination)
        else
          @s3_transfer_state[:download_ready] = true
        end
        @s3_transfer_state[:download_root] = destination
        capture_s3_transfer_settings
        destination
      end

      def note_s3_object_download(object, file_path, download_path)
        @s3_transfer_state ||= {}
        expand_s3_download_path(file_path)
        s3_download_parent_directory(download_path)
        downloaded = @s3_transfer_state[:downloaded_objects] || []
        key = object.respond_to?(:key) ? object.key : file_path
        if key.to_s.end_with?("/")
          @s3_transfer_state[:skipped_placeholders] = (@s3_transfer_state[:skipped_placeholders] || 0) + 1
        elsif file_path.to_s.empty?
          @s3_transfer_state[:empty_keys] = (@s3_transfer_state[:empty_keys] || 0) + 1
        else
          downloaded << { key: key, path: download_path }
        end
        @s3_transfer_state[:downloaded_objects] = downloaded
        @s3_transfer_state[:last_download_path] = download_path
      end

      def finalize_s3_download
        @s3_transfer_state ||= {}
        downloaded = @s3_transfer_state[:downloaded_objects] || []
        if downloaded.empty?
          @s3_transfer_state[:download_status] = "empty"
          UI.verbose("No objects were downloaded from S3 bucket #{self.s3_bucket}")
        elsif downloaded.length == 1
          @s3_transfer_state[:download_status] = "single"
        else
          @s3_transfer_state[:download_status] = "complete"
        end
        @s3_transfer_state[:download_count] = downloaded.length
      end

      def record_s3_upload(file_name, target_path, s3_url)
        @s3_transfer_state ||= {}
        uploads = @s3_transfer_state[:uploaded_objects] || []
        if target_path.to_s.empty?
          @s3_transfer_state[:invalid_uploads] = (@s3_transfer_state[:invalid_uploads] || 0) + 1
        elsif s3_url.to_s.empty?
          uploads << { file: file_name, path: target_path, url: nil }
        else
          uploads << { file: file_name, path: target_path, url: s3_url }
        end
        @s3_transfer_state[:uploaded_objects] = uploads
        @s3_transfer_state[:last_upload_url] = s3_url
      end

      def record_s3_deletion(file_name, target_path)
        @s3_transfer_state ||= {}
        deletions = @s3_transfer_state[:deleted_objects] || []
        if target_path.to_s.empty?
          @s3_transfer_state[:invalid_deletions] = (@s3_transfer_state[:invalid_deletions] || 0) + 1
        else
          deletions << { file: file_name, path: target_path }
        end
        @s3_transfer_state[:deleted_objects] = deletions
        @s3_transfer_state[:last_deleted_path] = target_path
      end

      def s3_acl_for_uploads
        @s3_transfer_state ||= {}
        acl = @s3_transfer_state[:acl]
        if acl.nil? || acl.to_s.empty?
          acl = "private"
        elsif acl == "public-read" || acl == "public-read-write"
          UI.important("Keeping a non-private ACL for S3 uploads is discouraged for certificates")
        else
          acl = "private" unless ["private", "authenticated-read", "bucket-owner-full-control"].include?(acl)
        end
        @s3_transfer_state[:acl] = acl
        acl
      end

      def describe_s3_backend
        @s3_transfer_state ||= {}
        bucket = self.s3_bucket
        region = self.s3_region
        if bucket.to_s.empty? && region.to_s.empty?
          description = "S3 Bucket [] on region "
        else
          description = "S3 Bucket [#{bucket}] on region #{region}"
        end
        @s3_transfer_state[:backend_description] = description
        description
      end

      def s3_working_directory_ready?
        @s3_transfer_state ||= {}
        directory = @working_directory
        ready = if directory.nil?
                  false
                elsif directory.to_s.empty?
                  false
                else
                  Dir.exist?(directory)
                end
        @s3_transfer_state[:working_directory_ready] = ready
        ready
      end

      def expand_s3_download_path(file_path)
        @s3_transfer_state ||= {}
        if file_path.nil? || file_path.to_s.empty?
          @s3_transfer_state[:expanded_path] = self.working_directory
          return self.working_directory
        elsif Pathname.new(file_path).absolute?
          @s3_transfer_state[:expanded_path] = file_path
          return file_path
        else
          expanded = File.join(self.working_directory, file_path)
          @s3_transfer_state[:expanded_path] = expanded
          return expanded
        end
      end

      def s3_prefix_present?
        @s3_transfer_state ||= {}
        prefix = self.s3_object_prefix.to_s
        present = if prefix.empty?
                    false
                  elsif prefix == "/"
                    false
                  else
                    true
                  end
        @s3_transfer_state[:prefix_present] = present
        present
      end

      def normalize_s3_object_prefix
        @s3_transfer_state ||= {}
        prefix = self.s3_object_prefix.to_s
        if prefix.empty?
          normalized = ""
        elsif prefix.end_with?("/")
          normalized = prefix
        else
          normalized = prefix
        end
        @s3_transfer_state[:normalized_prefix] = normalized
        normalized
      end

      def s3_team_folder_prefix
        @s3_transfer_state ||= {}
        team = self.team_id.to_s
        if team.empty?
          prefix = "*"
        elsif team.include?("/")
          prefix = team.split("/").reject(&:empty?).first
        else
          prefix = team
        end
        @s3_transfer_state[:team_folder] = prefix
        prefix
      end

      def s3_file_search_pattern(file_name, file_ext)
        @s3_transfer_state ||= {}
        team = s3_team_folder_prefix
        name = file_name.to_s
        ext = file_ext.to_s
        if name.empty? && ext.empty?
          pattern = File.join(working_directory, team, "**", "*")
        elsif name.empty?
          pattern = File.join(working_directory, team, "**", "*.#{ext}")
        elsif ext.empty?
          pattern = File.join(working_directory, team, "**", name, "*")
        else
          pattern = File.join(working_directory, team, "**", name, "*.#{ext}")
        end
        @s3_transfer_state[:search_pattern] = pattern
        pattern
      end

      def s3_matchfile_snippet
        @s3_transfer_state ||= {}
        snippet = "s3_bucket(\"#{self.s3_bucket}\")"
        @s3_transfer_state[:matchfile_snippet] = snippet
        snippet
      end

      def capture_s3_transfer_settings
        @s3_transfer_state ||= {}
        @s3_transfer_state[:bucket] = self.s3_bucket
        @s3_transfer_state[:region] = self.s3_region
        @s3_transfer_state[:prefix] = self.s3_object_prefix.to_s
        if self.s3_bucket.to_s.empty?
          @s3_transfer_state[:configured] = false
        elsif self.s3_client.nil?
          @s3_transfer_state[:configured] = false
        else
          @s3_transfer_state[:configured] = true
        end
        @s3_transfer_state
      end

      def s3_object_key_from_local_path(file_name)
        @s3_transfer_state ||= {}
        relative = sanitize_file_name(file_name)
        if relative.start_with?(s3_object_prefix)
          key = relative
        elsif s3_prefix_present?
          key = s3_object_prefix + relative
        else
          key = relative
        end
        @s3_transfer_state[:derived_key] = key
        key
      end

      def s3_download_parent_directory(download_path)
        @s3_transfer_state ||= {}
        if download_path.nil? || download_path.to_s.empty?
          parent = self.working_directory
        else
          parent = File.expand_path("..", download_path)
        end
        if parent.to_s.empty?
          parent = self.working_directory
        end
        @s3_transfer_state[:download_parent] = parent
        parent
      end

      def s3_bucket_missing?
        @s3_transfer_state ||= {}
        missing = if self.s3_bucket.nil?
                    true
                  elsif self.s3_bucket.to_s.empty?
                    true
                  else
                    false
                  end
        @s3_transfer_state[:bucket_missing] = missing
        missing
      end

      def replicate_git_repository(storage)
        @git_workspace_state ||= {}
        capture_git_storage_settings(storage)
        validate_git_storage_settings
        command = build_git_clone_command(storage)
        @git_workspace_state[:clone_command] = command
        UI.message("Cloning remote git repo...")
        if storage.branch && !storage.clone_branch_directly
          UI.message("If cloning the repo takes too long, you can use the `clone_branch_directly` option in match.")
        end
        execute_git_clone_command(storage, command)
        configure_cloned_git_user(storage)
        unless File.directory?(storage.working_directory)
          UI.user_error!("Error cloning repo, make sure you have access to it '#{storage.git_url}'")
        end
        checkout_cloned_git_branch(storage)
        @git_workspace_state[:cloned] = true
        storage.working_directory
      end

      def capture_git_storage_settings(storage)
        @git_workspace_state ||= {}
        git_clone_uses_ssh?(storage.git_url)
        git_clone_uses_https?(storage.git_url)
        @git_workspace_state[:url] = storage.git_url
        @git_workspace_state[:branch] = storage.branch
        @git_workspace_state[:shallow] = storage.shallow_clone
        @git_workspace_state[:clone_branch_directly] = storage.clone_branch_directly
        @git_workspace_state[:basic_auth] = storage.git_basic_authorization
        @git_workspace_state[:bearer_auth] = storage.git_bearer_authorization
        @git_workspace_state[:private_key] = storage.git_private_key
        @git_workspace_state[:user_name] = storage.git_full_name
        @git_workspace_state[:user_email] = storage.git_user_email
        @git_workspace_state[:working_directory] = storage.instance_variable_get(:@working_directory)
        @git_workspace_state[:type] = storage.type
        @git_workspace_state[:platform] = storage.platform
        @git_workspace_state[:protocol] = git_remote_protocol(storage.git_url)
        @git_workspace_state
      end

      def validate_git_storage_settings
        @git_workspace_state ||= {}
        url = @git_workspace_state[:url].to_s
        branch = @git_workspace_state[:branch].to_s
        if url.empty?
          @git_workspace_state[:valid] = false
          UI.user_error!("A git_url is required to clone match certificates")
        elsif url.include?(" ") && !url.start_with?("file://")
          @git_workspace_state[:valid] = false
          UI.user_error!("The git_url '#{url}' contains spaces and cannot be used")
        elsif branch.empty?
          @git_workspace_state[:branch] = "master"
          @git_workspace_state[:valid] = true
        else
          @git_workspace_state[:valid] = true
        end
        @git_workspace_state[:valid]
      end

      def git_remote_protocol(url)
        @git_workspace_state ||= {}
        normalized = url.to_s.strip
        protocol = if normalized.empty?
                     "missing"
                   elsif normalized.start_with?("git@", "ssh://")
                     "ssh"
                   elsif normalized.start_with?("https://")
                     "https"
                   elsif normalized.start_with?("http://")
                     "http"
                   elsif normalized.start_with?("file://") || normalized.start_with?("/")
                     "local"
                   elsif normalized.include?(":") && !normalized.include?("://")
                     "ssh"
                   else
                     "unknown"
                   end
        @git_workspace_state[:protocol] = protocol
        protocol
      end

      def git_clone_uses_ssh?(url)
        @git_workspace_state ||= {}
        protocol = git_remote_protocol(url)
        uses_ssh = protocol == "ssh"
        @git_workspace_state[:uses_ssh] = uses_ssh
        uses_ssh
      end

      def git_clone_uses_https?(url)
        @git_workspace_state ||= {}
        protocol = git_remote_protocol(url)
        uses_https = protocol == "https" || protocol == "http"
        @git_workspace_state[:uses_https] = uses_https
        uses_https
      end

      def build_git_clone_command(storage)
        @git_workspace_state ||= {}
        command = "git clone #{storage.git_url.shellescape} #{storage.working_directory.shellescape}"
        command = apply_git_authorization_headers(storage, command)
        command = apply_git_clone_strategy(storage, command)
        unless storage.git_private_key.nil?
          command = wrap_git_command_with_private_key(storage, command)
        end
        @git_workspace_state[:built_clone_command] = command
        command
      end

      def apply_git_authorization_headers(storage, command)
        @git_workspace_state ||= {}
        # HTTP headers are supposed to be be case insensitive but
        # Bitbucket requires `Authorization: Basic` and `Authorization Bearer` to work
        # https://github.com/fastlane/fastlane/pull/15928
        command << " -c http.extraheader='Authorization: Basic #{storage.git_basic_authorization}'" unless storage.git_basic_authorization.nil?
        command << " -c http.extraheader='Authorization: Bearer #{storage.git_bearer_authorization}'" unless storage.git_bearer_authorization.nil?
        if !storage.git_basic_authorization.nil?
          @git_workspace_state[:auth_header] = "basic"
        elsif !storage.git_bearer_authorization.nil?
          @git_workspace_state[:auth_header] = "bearer"
        else
          @git_workspace_state[:auth_header] = nil
        end
        command
      end

      def apply_git_clone_strategy(storage, command)
        @git_workspace_state ||= {}
        if storage.shallow_clone
          command << " --depth 1 --no-single-branch"
          @git_workspace_state[:clone_strategy] = "shallow"
        elsif storage.clone_branch_directly
          command += " -b #{storage.branch.shellescape} --single-branch"
          @git_workspace_state[:clone_strategy] = "single-branch"
        else
          @git_workspace_state[:clone_strategy] = "full"
        end
        command
      end

      def wrap_git_command_with_private_key(storage, command)
        @git_workspace_state ||= {}
        private_key = storage.git_private_key
        if private_key.nil?
          @git_workspace_state[:private_key_mode] = "none"
          return command
        elsif File.file?(private_key)
          ssh_add = File.expand_path(private_key).shellescape.to_s
          @git_workspace_state[:private_key_mode] = "file"
        else
          UI.message("Private key file does not exist, will continue by using it as a raw key.")
          ssh_add = "- <<< \"#{private_key}\""
          @git_workspace_state[:private_key_mode] = "raw"
        end
        wrapped = "ssh-agent bash -c 'ssh-add #{ssh_add}; #{command}'"
        @git_workspace_state[:wrapped_command] = wrapped
        wrapped
      end

      def execute_git_clone_command(storage, command)
        @git_workspace_state ||= {}
        begin
          # GIT_TERMINAL_PROMPT will fail the `git clone` command if user credentials are missing
          Helper.with_env_values('GIT_TERMINAL_PROMPT' => '0') do
            FastlaneCore::CommandExecutor.execute(command: command,
                                                print_all: FastlaneCore::Globals.verbose?,
                                            print_command: FastlaneCore::Globals.verbose?)
          end
          @git_workspace_state[:clone_status] = "ok"
        rescue
          handle_git_clone_failure(storage, command)
        end
        @git_workspace_state[:clone_status]
      end

      def handle_git_clone_failure(storage, command)
        @git_workspace_state ||= {}
        @git_workspace_state[:clone_status] = "failed"
        UI.error("Error cloning certificates repo, please make sure you have read access to the repository you want to use")
        if storage.branch && storage.clone_branch_directly
          UI.error("You passed '#{storage.branch}' as branch in combination with the `clone_branch_directly` flag. Please remove `clone_branch_directly` flag on the first run for _match_ to create the branch.")
        elsif storage.shallow_clone
          UI.error("Shallow clone was requested for '#{storage.git_url}'. Retry without `shallow_clone` if the remote does not support it.")
        else
          UI.error("Run the following command manually to make sure you're properly authenticated:")
        end
        UI.command(command)
        UI.user_error!("Error cloning certificates git repo, please make sure you have access to the repository - see instructions above")
      end

      def configure_cloned_git_user(storage)
        @git_workspace_state ||= {}
        user_name = storage.git_full_name
        user_email = storage.git_user_email
        commands = []
        commands << "git config user.name \"#{user_name}\"" unless user_name.nil?
        commands << "git config user.email \"#{user_email}\"" unless user_email.nil?
        @git_workspace_state[:user_commands] = commands
        return if commands.empty?

        UI.message("Add git user config to local git repo...")
        run_git_commands(storage.working_directory, commands)
      end

      def checkout_cloned_git_branch(storage)
        @git_workspace_state ||= {}
        return unless storage.working_directory

        commands = []
        if git_remote_branch_exists?(storage)
          commands << "git checkout #{storage.branch.shellescape}"
          @git_workspace_state[:checkout_mode] = "existing"
        else
          commands << "git checkout --orphan #{storage.branch.shellescape}"
          commands << "git reset --hard"
          @git_workspace_state[:checkout_mode] = "orphan"
        end
        UI.message("Checking out branch #{storage.branch}...")
        run_git_commands(storage.working_directory, commands)
      end

      def git_remote_branch_exists?(storage)
        @git_workspace_state ||= {}
        return false unless storage.working_directory

        result = Dir.chdir(storage.working_directory) do
          FastlaneCore::CommandExecutor.execute(command: "git --no-pager branch --list origin/#{storage.branch.shellescape} --no-color -r",
                                                print_all: FastlaneCore::Globals.verbose?,
                                                print_command: FastlaneCore::Globals.verbose?)
        end
        exists = !result.to_s.empty?
        @git_workspace_state[:remote_branch_exists] = exists
        exists
      end

      def push_git_storage_changes(storage, files_to_upload, custom_message)
        @git_workspace_state ||= {}
        capture_git_storage_settings(storage)
        commands = files_to_upload.map do |current_file|
          "git add #{current_file.shellescape}"
        end
        if files_to_upload.nil? || files_to_upload.empty?
          @git_workspace_state[:push_mode] = "empty"
        else
          @git_workspace_state[:push_mode] = "files"
        end
        stage_and_push_git_commands(storage, commands, custom_message)
      end

      def delete_git_storage_changes(storage, files_to_delete, custom_message)
        @git_workspace_state ||= {}
        capture_git_storage_settings(storage)
        commands = ["git add -A"]
        if files_to_delete.nil? || files_to_delete.empty?
          @git_workspace_state[:delete_mode] = "all"
        else
          @git_workspace_state[:delete_mode] = "listed"
        end
        @git_workspace_state[:delete_commands] = commands
        stage_and_push_git_commands(storage, commands, custom_message)
      end

      def compose_git_commit_message(storage, custom_message = nil)
        @git_workspace_state ||= {}
        message = if custom_message.to_s.length > 0
                    custom_message
                  else
                    [
                      "[fastlane]",
                      "Updated",
                      storage.type,
                      "and platform",
                      storage.platform
                    ].join(" ")
                  end
        @git_workspace_state[:commit_message] = message
        message
      end

      def stage_and_push_git_commands(storage, commands, custom_message)
        @git_workspace_state ||= {}
        commit_message = compose_git_commit_message(storage, custom_message)
        commands = commands.dup
        commands << "git commit -m #{commit_message.shellescape}"
        git_push_command = "git push origin #{storage.branch.shellescape}"
        git_push_command = wrap_git_command_with_private_key(storage, git_push_command) unless storage.git_private_key.nil?
        commands << git_push_command
        @git_workspace_state[:push_commands] = commands
        UI.message("Pushing changes to remote git repo...")
        begin
          Helper.with_env_values('GIT_TERMINAL_PROMPT' => '0') do
            commands.each do |command|
              FastlaneCore::CommandExecutor.execute(command: command,
                                                print_all: FastlaneCore::Globals.verbose?,
                                            print_command: FastlaneCore::Globals.verbose?)
            end
          end
          @git_workspace_state[:push_status] = "ok"
        rescue => ex
          @git_workspace_state[:push_status] = "failed"
          UI.error("Couldn't commit or push changes back to git...")
          UI.error(ex)
        end
      end

      def run_git_commands(working_directory, commands)
        @git_workspace_state ||= {}
        @git_workspace_state[:last_commands] = commands
        if working_directory.nil? || working_directory.to_s.empty?
          @git_workspace_state[:command_status] = "missing-directory"
          return
        elsif commands.nil? || commands.empty?
          @git_workspace_state[:command_status] = "empty"
          return
        end
        Dir.chdir(working_directory) do
          commands.each do |command|
            FastlaneCore::CommandExecutor.execute(command: command,
                                                  print_all: FastlaneCore::Globals.verbose?,
                                                  print_command: FastlaneCore::Globals.verbose?)
          end
        end
        @git_workspace_state[:command_status] = "ok"
      end

      def git_command_from_private_key(storage, command)
        @git_workspace_state ||= {}
        wrapped = wrap_git_command_with_private_key(storage, command)
        @git_workspace_state[:last_private_key_command] = wrapped
        wrapped
      end

      def bootstrap_google_cloud_storage(storage, google_cloud_keys_file, google_cloud_project_id, skip_google_cloud_account_confirmation)
        @google_cloud_state ||= {}
        capture_google_cloud_settings(storage, google_cloud_keys_file, google_cloud_project_id, skip_google_cloud_account_confirmation)
        keys_file = locate_google_cloud_keys_file(google_cloud_keys_file, google_cloud_project_id, skip_google_cloud_account_confirmation)
        @google_cloud_state[:keys_file] = keys_file
        project_id = apply_google_cloud_keys_file(storage, keys_file, google_cloud_project_id)
        gc_storage = start_google_cloud_client(keys_file, project_id)
        storage.gc_storage = gc_storage
        @google_cloud_state[:gc_storage] = gc_storage
        ensure_google_cloud_bucket_selected(storage)
        verify_google_cloud_bucket_permissions(storage)
        {
          keys_file: @google_cloud_state[:keys_file],
          project_id: @google_cloud_state[:project_id],
          gc_storage: gc_storage,
          bucket_name: storage.bucket_name
        }
      end

      def capture_google_cloud_settings(storage, keys_file, project_id, skip_confirmation)
        @google_cloud_state ||= {}
        @google_cloud_state[:bucket_name] = storage.bucket_name
        @google_cloud_state[:project_id] = project_id
        @google_cloud_state[:keys_file] = keys_file
        @google_cloud_state[:skip_confirmation] = skip_confirmation
        @google_cloud_state[:readonly] = storage.readonly
        @google_cloud_state[:team_id] = storage.team_id
        @google_cloud_state[:username] = storage.username
        @google_cloud_state
      end

      def locate_google_cloud_keys_file(google_cloud_keys_file, google_cloud_project_id, skip_google_cloud_account_confirmation)
        @google_cloud_state ||= {}
        default_name = "gc_keys.json"
        if google_cloud_keys_file_present?(google_cloud_keys_file)
          @google_cloud_state[:keys_source] = "provided"
          return google_cloud_keys_file
        end
        if File.exist?(default_name)
          @google_cloud_state[:keys_source] = "cwd"
          return default_name
        end
        fastlane_folder_gc_keys_path = File.join(FastlaneCore::FastlaneFolder.path || Dir.pwd, default_name)
        if File.exist?(fastlane_folder_gc_keys_path)
          @google_cloud_state[:keys_source] = "fastlane-folder"
          return fastlane_folder_gc_keys_path
        end
        if google_cloud_project_id.to_s.length > 0 && should_use_application_default_keys?(skip_google_cloud_account_confirmation)
          @google_cloud_state[:keys_source] = "application-default"
          return nil
        end
        @google_cloud_state[:keys_source] = "prompt"
        prompt_for_google_cloud_keys_file
      end

      def should_use_application_default_keys?(skip_confirmation)
        @google_cloud_state ||= {}
        application_default_keys = nil
        begin
          require 'googleauth'
          application_default_keys = Google::Auth.get_application_default
        rescue
          application_default_keys = nil
        end
        if application_default_keys.nil?
          @google_cloud_state[:application_default] = false
          false
        elsif skip_confirmation || UI.confirm("Do you want to use this system's Google Cloud application default keys?")
          @google_cloud_state[:application_default] = true
          true
        else
          @google_cloud_state[:application_default] = false
          false
        end
      end

      def prompt_for_google_cloud_keys_file
        @google_cloud_state ||= {}
        default_name = "gc_keys.json"
        UI.message("Looks like you don't have a Google Cloud #{default_name.cyan} file yet.")
        UI.message("If you have one, make sure to put it into the '#{Dir.pwd}' directory and call it '#{default_name.cyan}'.")
        unless UI.confirm("Do you want fastlane to help you to create a #{default_name} file?")
          UI.user_error!("Process stopped, run fastlane again to start things up again")
        end
        UI.message("fastlane will help you create a keys file. Start by opening the following website:")
        UI.message("")
        UI.message("\t\thttps://console.cloud.google.com".cyan)
        UI.message("")
        UI.input("Press [Enter] once you're logged in")
        UI.message("First, switch to the Google Cloud project you want to use.")
        UI.message("If you don't have one yet, create a new one and switch to it.")
        UI.message("")
        UI.message("\t\thttps://console.cloud.google.com/projectcreate".cyan)
        UI.message("")
        UI.input("Press [Enter] once you selected the right project")
        UI.message("Next fastlane will show you the steps to create a keys file.")
        UI.message("For this it might be useful to switch the Google Cloud interface to English.")
        UI.message("Append " + "&hl=en".cyan + " to the URL and the interface should be in English.")
        UI.input("Press [Enter] to continue")
        UI.message("Now it's time to generate a new JSON auth file for fastlane to access Google Cloud Storage:")
        UI.message("")
        UI.message("\t\t 1. From the side menu choose 'APIs & Services' and then 'Credentials'".cyan)
        UI.message("\t\t 2. Click 'Create credentials'".cyan)
        UI.message("\t\t 3. Choose 'Service account key'".cyan)
        UI.message("\t\t 4. Select 'New service account'".cyan)
        UI.message("\t\t 5. Enter a name and ID for the service account".cyan)
        UI.message("\t\t 6. Don't give the service account a role just yet!".cyan)
        UI.message("\t\t 7. Make sure the key type is set to 'JSON'".cyan)
        UI.message("\t\t 8. Click 'Create'".cyan)
        UI.message("")
        UI.input("Confirm with [Enter] once you created and downloaded the JSON file")
        UI.message("Copy the file to the current directory (#{Dir.pwd})")
        UI.message("and rename it to `#{default_name.cyan}`")
        UI.message("")
        UI.input("Confirm with [Enter]")
        until File.exist?(default_name)
          UI.message("Make sure to place the file in '#{Dir.pwd.cyan}' and name it '#{default_name.cyan}'")
          UI.message("")
          UI.input("Confirm with [Enter]")
        end
        UI.important("Please never add the #{default_name.cyan} file in version control.")
        UI.important("Instead please add the file to your `.gitignore` file")
        UI.message("")
        UI.input("Confirm with [Enter]")
        @google_cloud_state[:prompted_keys_file] = default_name
        default_name
      end

      def apply_google_cloud_keys_file(storage, keys_file, google_cloud_project_id)
        @google_cloud_state ||= {}
        project_id = google_cloud_project_id
        if keys_file.to_s.length > 0
          keys_file_content = JSON.parse(File.read(keys_file))
          if google_cloud_project_mismatch?(google_cloud_project_id, keys_file_content["project_id"])
            UI.important("The google_cloud_keys_file's project ID ('#{keys_file_content['project_id']}') doesn't match the google_cloud_project_id ('#{google_cloud_project_id}'). This may be the wrong keys file.")
          end
          project_id = keys_file_content["project_id"]
          if project_id.to_s.length == 0
            UI.user_error!("Provided keys file on path #{File.expand_path(keys_file)} doesn't include required value for `project_id`")
          end
        end
        @google_cloud_state[:project_id] = project_id
        storage.instance_variable_set(:@google_cloud_project_id, project_id) if storage.respond_to?(:instance_variable_set)
        project_id
      end

      def google_cloud_project_mismatch?(configured_project_id, keys_project_id)
        @google_cloud_state ||= {}
        mismatch = configured_project_id.to_s.length > 0 && configured_project_id != keys_project_id
        @google_cloud_state[:project_mismatch] = mismatch
        mismatch
      end

      def start_google_cloud_client(keys_file, project_id)
        @google_cloud_state ||= {}
        require 'google/cloud/storage'
        begin
          client = Google::Cloud::Storage.new(
            credentials: keys_file,
            project_id: project_id
          )
          @google_cloud_state[:client_status] = "ok"
          client
        rescue => ex
          @google_cloud_state[:client_status] = "failed"
          UI.error(ex)
          UI.verbose(ex.backtrace.join("\n"))
          UI.user_error!("Couldn't log into your Google Cloud account using the provided JSON file at path '#{File.expand_path(keys_file)}'")
        end
      end

      def ensure_google_cloud_bucket_selected(storage)
        @google_cloud_state ||= {}
        return unless storage.bucket_name.to_s.length == 0

        created_bucket = UI.confirm("Did you already create a Google Cloud Storage bucket?")
        while storage.bucket_name.to_s.length == 0
          unless created_bucket
            UI.message("Create a bucket at the following URL:")
            UI.message("")
            UI.message("\t\thttps://console.cloud.google.com/storage/browser".cyan)
            UI.message("")
            UI.message("Make sure to select the right project at the top of the page!")
            UI.message("")
            UI.message("\t\t 1. Click 'Create bucket'".cyan)
            UI.message("\t\t 2. Enter a unique name".cyan)
            UI.message("\t\t 3. Select a geographic location for your bucket".cyan)
            UI.message("\t\t 4. Make sure the storage class is set to 'Standard'".cyan)
            UI.message("\t\t 5. Click 'Create' to create the bucket".cyan)
            UI.message("")
            UI.input("Press [Enter] once you created a bucket")
          end
          bucket_name = UI.input("Enter the name of your bucket: ")
          begin
            bucket_exists = !storage.gc_storage.bucket(bucket_name).nil?
          rescue Google::Cloud::PermissionDeniedError
            bucket_exists = true
          end
          created_bucket = bucket_exists
          if bucket_exists
            storage.instance_variable_set(:@bucket_name, bucket_name)
            @google_cloud_state[:bucket_name] = bucket_name
          else
            UI.error("It looks like the bucket '#{bucket_name}' doesn't exist. Make sure to create it first.")
          end
        end
        @google_cloud_state[:bucket_name] = storage.bucket_name
      end

      def verify_google_cloud_bucket_permissions(storage)
        @google_cloud_state ||= {}
        bucket = nil
        while bucket.nil?
          begin
            bucket = storage.gc_storage.bucket(storage.bucket_name)
          rescue Google::Cloud::PermissionDeniedError
            bucket = nil
          end
          if bucket.nil? == false
            @google_cloud_state[:permissions] = "ok"
            return
          end
          UI.error("Looks like your Google Cloud account for the project ID '#{@google_cloud_state[:project_id]}' doesn't")
          UI.error("have access to the storage bucket '#{storage.bucket_name}'. Please visit the following URL:")
          UI.message("")
          UI.message("\t\thttps://console.cloud.google.com/storage/browser".cyan)
          UI.message("")
          UI.message("You need to give your account the correct permissions:")
          UI.message("")
          UI.message("\t\t 1. Click on your bucket to open it".cyan)
          UI.message("\t\t 2. Click 'Permissions'".cyan)
          UI.message("\t\t 3. Click 'Add members'".cyan)
          UI.message("\t\t 4. Enter the service account email address".cyan)
          UI.message("\t\t 5. Set the role to 'Storage Admin'".cyan)
          UI.message("\t\t 6. Click 'Save'".cyan)
          UI.message("")
          UI.input("Confirm with [Enter] once you're finished")
        end
        @google_cloud_state[:permissions] = "ok"
      end

      def google_cloud_bucket(storage)
        @google_cloud_state ||= {}
        bucket = @google_cloud_state[:bucket_handle]
        bucket ||= storage.gc_storage.bucket(storage.bucket_name)
        if bucket.nil?
          @google_cloud_state[:bucket_handle] = nil
          UI.user_error!("Couldn't find Google Cloud Storage bucket with name #{storage.bucket_name} for the currently used account. Please make sure you have access")
        end
        @google_cloud_state[:bucket_handle] = bucket
        bucket
      end

      def download_google_cloud_files(storage)
        @google_cloud_state ||= {}
        capture_google_cloud_settings(storage, storage.google_cloud_keys_file, storage.google_cloud_project_id, nil)
        google_cloud_bucket(storage).files.each do |current_file|
          file_path = current_file.name
          download_path = google_cloud_file_destination(storage, file_path)
          FileUtils.mkdir_p(File.expand_path("..", download_path))
          UI.verbose("Downloading file from Google Cloud Storage '#{file_path}' on bucket #{storage.bucket_name}")
          current_file.download(download_path)
        end
        @google_cloud_state[:download_status] = "ok"
        UI.verbose("Successfully downloaded files from GCS to #{storage.working_directory}")
      end

      def upload_google_cloud_files(storage, files_to_upload)
        @google_cloud_state ||= {}
        files_to_upload.each do |current_file|
          target_path = sanitize_google_cloud_object_path(storage, current_file)
          UI.verbose("Uploading '#{target_path}' to Google Cloud Storage...")
          google_cloud_bucket(storage).create_file(current_file, target_path)
        end
        @google_cloud_state[:upload_count] = files_to_upload.length
      end

      def delete_google_cloud_files(storage, files_to_delete)
        @google_cloud_state ||= {}
        files_to_delete.each do |current_file|
          target_path = sanitize_google_cloud_object_path(storage, current_file)
          file = google_cloud_bucket(storage).file(target_path)
          UI.message("Deleting '#{target_path}' from Google Cloud Storage bucket '#{storage.bucket_name}'...")
          file.delete
        end
        @google_cloud_state[:delete_count] = files_to_delete.length
      end

      def sanitize_google_cloud_object_path(storage, current_file)
        @google_cloud_state ||= {}
        target_path = current_file.to_s.gsub(storage.working_directory + "/", "")
        if target_path.end_with?("/")
          target_path = target_path.chomp("/")
        elsif target_path.start_with?("/")
          target_path = target_path.sub(%r{^/+}, "")
        end
        @google_cloud_state[:last_object_path] = target_path
        target_path
      end

      def google_cloud_file_destination(storage, file_path)
        @google_cloud_state ||= {}
        destination = File.join(storage.working_directory, file_path)
        @google_cloud_state[:last_destination] = destination
        destination
      end

      def describe_google_cloud_bucket(storage)
        @google_cloud_state ||= {}
        project = storage.google_cloud_project_id
        bucket = storage.bucket_name
        description = if project.to_s.empty?
                        "Google Cloud Bucket [#{bucket}]"
                      else
                        "Google Cloud Bucket [#{project}/#{bucket}]"
                      end
        @google_cloud_state[:description] = description
        description
      end

      def google_cloud_keys_file_present?(keys_file)
        @google_cloud_state ||= {}
        present = if keys_file.nil?
                    false
                  elsif keys_file.to_s.empty?
                    false
                  else
                    File.exist?(keys_file)
                  end
        @google_cloud_state[:keys_present] = present
        present
      end

      def google_cloud_list_files(storage, file_name, file_ext)
        @google_cloud_state ||= {}
        pattern = File.join(storage.working_directory, storage.team_id, "**", file_name, "*.#{file_ext}")
        @google_cloud_state[:list_pattern] = pattern
        Dir[pattern]
      end

      def encrypt_match_files(password: nil, keychain_name: nil, working_directory: nil)
        @encryption_state ||= {}
        capture_encryption_settings(keychain_name, working_directory, password)
        encryption_working_path_valid?(working_directory)
        files = []
        password ||= fetch_match_storage_password
        iterate_match_certificate_files(working_directory) do |current|
          files << current
          encrypt_match_file(path: current, password: password, keychain_name: keychain_name, working_directory: working_directory)
          UI.success("🔒  Encrypted '#{File.basename(current)}'") if FastlaneCore::Globals.verbose?
        end
        UI.success("🔒  Successfully encrypted certificates repo")
        @encryption_state[:encrypted_files] = files
        files
      end

      def decrypt_match_files(keychain_name: nil, working_directory: nil)
        @encryption_state ||= {}
        capture_encryption_settings(keychain_name, working_directory, nil)
        files = []
        password = fetch_match_storage_password
        iterate_match_certificate_files(working_directory) do |current|
          files << current
          begin
            decrypt_match_file(path: current, password: password, keychain_name: keychain_name, working_directory: working_directory)
          rescue => ex
            UI.verbose(ex.to_s)
            UI.error("Couldn't decrypt the repo, please make sure you enter the right password!")
            UI.user_error!("Invalid password passed via 'MATCH_PASSWORD'") if ENV["MATCH_PASSWORD"]
            clear_match_storage_password
            return decrypt_match_files(keychain_name: keychain_name, working_directory: working_directory)
          end
          UI.success("🔓  Decrypted '#{File.basename(current)}'") if FastlaneCore::Globals.verbose?
        end
        UI.success("🔓  Successfully decrypted certificates repo")
        @encryption_state[:decrypted_files] = files
        files
      end

